import{c as i,Z as t,Q as l,j as g,m as a,o as r}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"九歌·山鬼","description":"","frontmatter":{"title":"九歌·山鬼","author":"屈原","dynasty":"战国"},"headers":[],"relativePath":"books/shici/chuci/3.md","filePath":"books/shici/chuci/3.md"}'),e={name:"books/shici/chuci/3.md"};function u(p,o,h,c,q,d){const n=t("PoemAuthor"),s=t("PoemNav");return l(),g("div",null,[o[0]||(o[0]=a('<h1 id="九歌·山鬼" tabindex="-1">九歌·山鬼 <a class="header-anchor" href="#九歌·山鬼" aria-label="Permalink to &quot;九歌·山鬼&quot;">​</a></h1><p><strong>[战国] <a href="/authors/quyuan.html">屈原</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>若有人兮山之阿，被薜荔兮带女萝。 既含睇兮又宜笑，子慕予兮善窈窕。 乘赤豹兮从文狸，辛夷车兮结桂旗。 被石兰兮带杜衡，折芳馨兮遗所思。</p><p>余处幽篁兮终不见天，路险难兮独后来。 表独立兮山之上，云容容兮而在下。 杳冥冥兮羌昼晦，东风飘兮神灵雨。 留灵修兮憺忘归，岁既晏兮孰华予？</p><p>采三秀兮于山间，石磊磊兮葛蔓蔓。 怨公子兮怅忘归，君思我兮不得闲。 山中人兮芳杜若，饮石泉兮荫松柏， 君思我兮然疑作。</p><p>雷填填兮雨冥冥，猨啾啾兮狖夜鸣。 风飒飒兮木萧萧，思公子兮徒离忧。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li><strong>山鬼</strong>：山中的女神，一说为山神。楚地多山，民间信仰山神，此为祭祀山神的乐歌。</li><li><strong>若有人</strong>：仿佛有人，形容山鬼若隐若现的姿态。</li><li><strong>山之阿</strong>：山的弯曲处，山隅。</li><li><strong>被</strong>：同&quot;披&quot;，披在身上。</li><li><strong>薜荔</strong>：一种蔓生香草，又称木莲。</li><li><strong>带</strong>：以……为带。</li><li><strong>女萝</strong>：一种攀援植物，即松萝。</li><li><strong>含睇</strong>：含情微视。睇，微微斜视，形容美目流盼。</li><li><strong>宜笑</strong>：笑起来很好看。</li><li><strong>子</strong>：你，指山鬼所爱慕的人。</li><li><strong>慕</strong>：爱慕。</li><li><strong>予</strong>：我，山鬼自称。</li><li><strong>善</strong>：善于，显得。</li><li><strong>窈窕</strong>：美好的样子，形容体态优美。</li><li><strong>赤豹</strong>：红色的豹子。传说山鬼乘赤豹。</li><li><strong>从</strong>：使……跟从。</li><li><strong>文狸</strong>：有花纹的野猫。狸，野猫。</li><li><strong>辛夷车</strong>：用辛夷木做的车。辛夷，香木名，即木兰。</li><li><strong>结</strong>：编结。</li><li><strong>桂旗</strong>：用桂树枝做的旗帜。</li><li><strong>石兰</strong>：香草名，即山兰。</li><li><strong>杜衡</strong>：香草名。</li><li><strong>芳馨</strong>：芳香的花朵。馨，散布很远的香气。</li><li><strong>遗</strong>：赠送。</li><li><strong>所思</strong>：所思念的人。</li><li><strong>余</strong>：我，山鬼自称。</li><li><strong>幽篁</strong>：幽深的竹林。篁，竹林。</li><li><strong>险难</strong>：艰险难行。</li><li><strong>独后来</strong>：独自来迟。</li><li><strong>表</strong>：突出地，高高地。</li><li><strong>独立</strong>：独自站立。</li><li><strong>容容</strong>：云气浮动的样子。</li><li><strong>杳冥冥</strong>：幽暗深远的样子。</li><li><strong>羌</strong>：楚地方言，句首语气词。</li><li><strong>昼晦</strong>：白天昏暗。</li><li><strong>飘</strong>：吹动。</li><li><strong>神灵雨</strong>：神灵降下的雨。</li><li><strong>留</strong>：挽留，等待。</li><li><strong>灵修</strong>：指山鬼所思念的人。灵修本为神明之称，此处指所思之人。</li><li><strong>憺</strong>：安然，安乐。</li><li><strong>岁既晏</strong>：年岁已晚。晏，晚，迟。</li><li><strong>孰华予</strong>：谁能使我青春常驻。华，同&quot;花&quot;，使……如花般美丽。</li><li><strong>三秀</strong>：灵芝草的别名。灵芝一年开花三次，故称三秀。</li><li><strong>磊磊</strong>：石头堆积的样子。</li><li><strong>葛</strong>：葛藤。</li><li><strong>蔓蔓</strong>：蔓延的样子。</li><li><strong>公子</strong>：指山鬼所思念的人。</li><li><strong>怅</strong>：惆怅。</li><li><strong>君</strong>：你，指所思之人。</li><li><strong>山中人</strong>：山鬼自称。</li><li><strong>芳杜若</strong>：像杜若一样芬芳。</li><li><strong>石泉</strong>：山石间的泉水。</li><li><strong>荫</strong>：遮蔽。</li><li><strong>然疑作</strong>：信疑交加。然，相信。疑，怀疑。</li><li><strong>填填</strong>：雷声轰鸣的样子。</li><li><strong>冥冥</strong>：昏暗的样子。</li><li><strong>猨</strong>：同&quot;猿&quot;，猿猴。</li><li><strong>啾啾</strong>：猿猴的哀鸣声。</li><li><strong>狖</strong>：一种长尾猿。</li><li><strong>飒飒</strong>：风声。</li><li><strong>萧萧</strong>：草木摇落的声音。</li><li><strong>徒</strong>：白白地。</li><li><strong>离忧</strong>：遭受忧愁。离，同&quot;罹&quot;，遭受。</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>仿佛有人啊在山弯深处，身披薜荔啊腰系女萝。 含情微视啊笑靥动人，你爱慕我啊我姿态窈窕。 乘坐赤豹啊花纹野猫跟随，辛夷木车啊桂树枝旗。 身披石兰啊腰系杜衡，折取芳香啊送给所思之人。</p><p>我身处幽深竹林啊终日不见天日，道路艰险啊我独来迟。 高高独立啊在山巅之上，云气浮动啊在我脚下。 幽暗深远啊白昼如晦，东风飘拂啊神灵降雨。 等待灵修啊安然忘归，年岁已晚啊谁使我青春常驻？</p><p>采摘灵芝啊在山间，石头堆积啊葛藤蔓延。 怨恨公子啊惆怅忘归，你想念我啊却不得空闲。 山中之人啊芬芳如杜若，饮用石泉啊松柏遮荫， 你想念我啊我又信又疑。</p><p>雷声轰鸣啊大雨冥冥，猿猴啾啾啊狖猴夜鸣。 风声飒飒啊木叶萧萧，思念公子啊白白忧愁。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《九歌·山鬼》是屈原《九歌》组诗中的名篇，是祭祀山神的乐歌。关于&quot;山鬼&quot;的身份，历来有不同说法，或以为是山神，或以为是巫山神女。从诗的内容来看，诗人塑造了一位美丽多情、纯洁忠贞的山中女神形象，她深情地等待所思之人的到来，却终究失望而归。</p><p>全诗以山鬼的口吻展开，首段描绘山鬼的装束与风姿：身披薜荔、腰系女萝，乘坐赤豹、文狸相随，辛夷为车、桂旗招展，石兰为衣、杜衡为带，一派山野仙姿。&quot;既含睇兮又宜笑&quot;一句，将山鬼的妩媚多情刻画得栩栩如生。</p><p>第二段写山鬼赴约的艰辛与等待的执着。她身处幽篁，路险来迟，独立山巅，云气在脚下浮动，白昼如晦，风雨交加，却依然&quot;留灵修兮憺忘归&quot;，甘愿等待。&quot;岁既晏兮孰华予&quot;一句，流露出对青春流逝的焦虑与对爱情的渴望。</p><p>第三段写山鬼的疑虑与哀怨。她采摘灵芝，却见&quot;石磊磊兮葛蔓蔓&quot;，道路阻隔；她怨恨公子不来，却又自我安慰&quot;君思我兮不得闲&quot;，最后陷入&quot;然疑作&quot;的矛盾心理，真实而动人。</p><p>末段以景结情，&quot;雷填填兮雨冥冥，猨啾啾兮狖夜鸣。风飒飒兮木萧萧&quot;，以凄风苦雨、猿啼枭鸣的悲凉景象，烘托出山鬼&quot;思公子兮徒离忧&quot;的无限惆怅。全诗情景交融，人神相恋的题材在屈原笔下写得缠绵悱恻、凄婉动人，是中国古代浪漫主义诗歌的杰作。</p>',20)),r(n,{name:"屈原",years:"约公元前340年－公元前278年",desc:"名平，字原，战国时期楚国诗人、政治家。中国浪漫主义文学的奠基人，“楚辞”的创立者和代表作家。代表作有《离骚》《九歌》《天问》等。",link:"/authors/quyuan"}),r(s)])}const f=i(e,[["render",u]]);export{m as __pageData,f as default};
